export class Dropdown {
  constructor(private triggerBtn: Locator) {}

  async selectOption(option: string) {
    await this.triggerBtn.click();
    const menu = this.triggerBtn.page().getByRole('listbox');
    await menu.getByRole('option', { name: option }).click();
  }
}

class FormComponent {
  async fillData(data: Record<string, string>) {
    for (const [key, value] of Object.entries(data)) {
      await this.root.getByLabel(key).fill(value);
    }
  }
}

